WITH base AS (SELECT *, ADD_MONTHS(delivered_date, 3) AS delivered_date_plus_months FROM shipments WHERE carrier = 'UPS'), shipments_stats AS (SELECT CASE WHEN cost >= 102 THEN 'high' WHEN cost >= 45 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(CASE WHEN status = 'LOST' THEN 1 ELSE 0 END) AS lost_count FROM base GROUP BY CASE WHEN cost >= 102 THEN 'high' WHEN cost >= 45 THEN 'mid' ELSE 'low' END) SELECT * FROM shipments_stats;
